const data = $input.all()[0].json.value || [];
if (data.length === 0) throw new Error('Stage 2 FATAL: Customer not found in SAC for ID: ' + $('Code in JavaScript').item.json.customerId);

const c = data[0];
return [{
  json: {
    customer: {
      customerId:     c.CUSTOMER,
      customerName:   c.CUSTOMERNAME || c.ORGANIZATIONBPNAME1 || null,
      customerName2:  c.ORGANIZATIONBPNAME2 || null,
      street:         c.STREETNAME || null,
      city:           c.CITYNAME || null,
      region:         c.REGION || null,
      postalCode:     c.POSTALCODE || null,
      country:        c.COUNTRY || null,
      accountGroup:   c.CUSTOMERACCOUNTGROUP || null,
      classification: c.CUSTOMERCLASSIFICATION || null
    }
  }
}];

const raw = $('When Executed by Another Workflow').first().json;
const stage1Raw = raw.items ? raw : (raw.stage1Data ? JSON.parse(raw.stage1Data) : null);
const stage1 = stage1Raw && stage1Raw.items ? stage1Raw : {
  items: [],
  _meta: {},
  envelope: {}
};
const customer    = $('Unpack Customer').first().json.customer;
const openOrders  = $('Unpack_to_OpenOrders').all().map(i => i.json);
const salesHist   = $('Unpack_To_History Orders').all().map(i => i.json);
const atsMap      = $('Unpack ATS').first().json.atsMap;
const matList     = $('Get Material Master').all().map(i => i.json);
const netSellRows = $('Unpack net Sell ALL').all().map(i => i.json);

// Build net sell pricing lookup — independent of ATS status
const netSellMap = {};
for (const p of netSellRows) {
  if (p.material) {
    netSellMap[p.material] = {
      netSellPrice: p.netSellPrice,
      currency: p.currency || 'USD'
    };
  }
}

// Build lookups
const openOrderMap = {};
for (const o of openOrders) {
  const mat = o.Material;
  if (!mat) continue;
  if (!openOrderMap[mat]) {
    openOrderMap[mat] = {
      material: mat,
      totalOpenQty: 0,
      earliestDelivery: null
    };
  }
  openOrderMap[mat].totalOpenQty += o.OpenQty || 0;
  if (o.RequestedDeliveryDate) {
    if (!openOrderMap[mat].earliestDelivery || o.RequestedDeliveryDate < openOrderMap[mat].earliestDelivery) {
      openOrderMap[mat].earliestDelivery = o.RequestedDeliveryDate;
    }
  }
}

const matMap = {};
const upcMap = {};
for (const m of matList) {
  if (m.MATERIAL) {
    matMap[m.MATERIAL] = { family: m.FAMILY, mgd2: m.MGD2, description: m.DESCRIPTION };
    if (m.UPC) upcMap[m.MATERIAL] = m.UPC;
  }
}

const salesHistMap = {};
for (const s of salesHist) {
  const mat = s.Material;
  if (!mat) continue;
  if (!salesHistMap[mat]) {
    salesHistMap[mat] = {
      material: mat,
      totalShippedQty: 0,
      totalNetAmount: 0,
      orderCount: 0
    };
  }
  salesHistMap[mat].totalShippedQty += s.ShippedQty || 0;
  salesHistMap[mat].totalNetAmount  += s.NetAmount || 0;
  salesHistMap[mat].orderCount      += 1;
}

// Enrich each customer item with SAC data
// Discontinued items are filtered out here to reduce downstream token costs
const enrichedItems = stage1.items
  .map(item => {
    const mat = item.mfrItemNumber;
    const ats = mat && atsMap[mat] ? atsMap[mat].ats : null;
    const oo  = mat ? openOrderMap[mat] : null;
    const sh  = mat ? salesHistMap[mat] : null;
    const mm  = mat ? matMap[mat] : null;
    const np  = mat ? netSellMap[mat] : null;
    const sacUpc      = upcMap[mat] ?? '';
    const customerUpc = item.upc ?? '';
    return {
      ...item,
      sacData: {
        qtyAvailableToSell:  ats,
        netSellPrice:        np ? np.netSellPrice : (mat && atsMap[mat] ? atsMap[mat].netSellPrice || 0 : 0),
        currency:            np ? np.currency : (mat && atsMap[mat] ? atsMap[mat].currency || 'USD' : 'USD'),
        openOrderQty:        oo ? oo.totalOpenQty : 0,
        earliestDelivery:    oo ? oo.earliestDelivery : null,
        totalShippedQty:     sh ? sh.totalShippedQty : 0,
        totalNetAmount:      sh ? sh.totalNetAmount : 0,
        orderCount:          sh ? sh.orderCount : 0,
        hasOpenOrder:        oo !== null && oo !== undefined,
        family:              mm ? mm.family : null,
        mgd2:                mm ? mm.mgd2 : null,
        upc:                 sacUpc,
        upcMismatch:         customerUpc && sacUpc && customerUpc !== sacUpc ? true : false
      }
    };
  })
  .filter(item => {
    // Remove discontinued items — they consume tokens at every stage
    // with no recommendation value. Filter after enrichment so we have
    // family/MGD2 data from SAC to make the determination.
    const family = (item.sacData?.family ?? '').toUpperCase();
    const mgd2   = (item.sacData?.mgd2   ?? '').toUpperCase();
    return family !== 'DISCONTINUED' && mgd2 !== 'DISCONTINUED';
  });

// Find items customer doesn't carry but Acme has in stock
const customerMaterials = new Set(
  enrichedItems
    .filter(i => i.mfrItemNumber)
    .map(i => i.mfrItemNumber)
);

const opportunityItems = Object.values(atsMap)
  .filter(q => {
    if (q.ats <= 0 || customerMaterials.has(q.material)) return false;
    // Also exclude discontinued opportunity items
    const mm = matMap[q.material];
    if (!mm) return true;
    const family = (mm.family ?? '').toUpperCase();
    const mgd2   = (mm.mgd2   ?? '').toUpperCase();
    return family !== 'DISCONTINUED' && mgd2 !== 'DISCONTINUED';
  })
  .map(q => {
    const oo = openOrderMap[q.material] ?? null;
    const np = netSellMap[q.material] ?? null;
    return {
      material:         q.material,
      ats:              q.ats,
      netSellPrice:     np ? np.netSellPrice : (q.netSellPrice || 0),
      currency:         np ? np.currency : (q.currency || 'USD'),
      salesData:        salesHistMap[q.material] || null,
      openOrderQty:     oo ? oo.totalOpenQty : 0,
      earliestDelivery: oo ? oo.earliestDelivery : null,
      hasOpenOrder:     oo !== null,
      upc:              upcMap[q.material] ?? ''
    };
  });

const workingObject = {
  ...stage1,
  customer,
  items: enrichedItems,
  openOrders,
  availability:    Object.values(atsMap),
  topItems:        [],
  salesHistory:    salesHist,
  opportunityItems,
  _meta: {
    ...stage1._meta,
    stage2CompletedAt: new Date().toISOString(),
    openOrderCount:    openOrders.length,
    salesHistoryCount: salesHist.length,
    availabilityCount: Object.keys(atsMap).length,
    opportunityCount:  opportunityItems.length
  }
};

return [{ json: workingObject }];

const input = $input.all();

const customerId = $input.all()[0].json.customerId ?? $input.all()[0].json.envelope?.customerId ?? null;
if (!customerId) throw new Error('Stage 2 FATAL: No customer ID received from Stage 1');

const d = new Date();
d.setFullYear(d.getFullYear() - 1);
const twelveMonthsAgo = d.toISOString().split('T')[0];

console.log('RAW INPUT:', JSON.stringify(input));

return [{ json: { customerId, twelveMonthsAgo } }];

const records = $input.all()[0].json.value || [];
const allowedGroups = ['10', '11', '12', '15'];
const twelveMonthsAgo = new Date();
twelveMonthsAgo.setFullYear(twelveMonthsAgo.getFullYear() - 1);
const cutoffDate = twelveMonthsAgo.toISOString().split('T')[0];
const rows = [];
for (const r of records) {
  const customerGroup = r.CUSTOMERGROUP || r.CustomerGroup || null;
  if (!allowedGroups.includes(String(customerGroup))) continue;
  const deliveryStatus = r.DELIVERYSTATUS || r.DeliveryStatus || null;
  if (deliveryStatus !== 'B' && deliveryStatus !== 'C') continue;
  const orderDate = r.SALESORDERDATE || r.SalesOrderDate || null;
if (orderDate && orderDate < cutoffDate) continue;
  const requestedQty = r.REQUESTEDQUANTITY || r.RequestedQuantity || 0;
  const confirmedQty = r.CONFDDELIVQTYINORDERQTYUNIT || r.ConfdDelivQtyInOrderQtyUnit || 0;
  const remainingQty = requestedQty - confirmedQty;
 rows.push({
    SoldToParty:           r.SOLDTOPARTY || r.SoldToParty || null,
    Material:              r.MATERIAL || r.Material || null,
    SalesOrderDate:        r.SALESORDERDATE || r.SalesOrderDate || null,
    RequestedDeliveryDate: r.REQUESTEDDELIVERYDATE || r.RequestedDeliveryDate || null,
    DeliveryStatus:        deliveryStatus,
    RequestedQty:          requestedQty,
    ShippedQty:            confirmedQty,
    RemainingQty:          remainingQty,
    NetAmount:             r.NETAMOUNT || r.NetAmount || 0   // ← add this
});
}
return rows.map(r => ({ json: r }));

const records = $input.all()[0].json.value || [];
const allowedGroups = ['10', '11', '12', '15'];
const rows = [];
for (const r of records) {
  const customerGroup = r.CUSTOMERGROUP || r.CustomerGroup || null;
  if (!allowedGroups.includes(String(customerGroup))) continue;
  const deliveryStatus = r.DELIVERYSTATUS || r.DeliveryStatus || null;
  if (deliveryStatus === 'C') continue;
  const requestedQty = r.REQUESTEDQUANTITY || r.RequestedQuantity || 0;
  const confirmedQty = r.CONFDDELIVQTYINORDERQTYUNIT || r.ConfdDelivQtyInOrderQtyUnit || 0;
  const openQty = requestedQty - confirmedQty;
  rows.push({
    SoldToParty: r.SOLDTOPARTY || r.SoldToParty || null,
    Material: r.MATERIAL || r.Material || null,
    SalesOrderDate: r.SALESORDERDATE || r.SalesOrderDate || null,
    RequestedDeliveryDate: r.REQUESTEDDELIVERYDATE || r.RequestedDeliveryDate || null,
    OpenQty: openQty
  });
}
return rows.map(r => ({ json: r }));

const items = $input.all();
const atsMap = {};
for (const item of items) {
  const r = item.json;
  const mat = r.MATERIAL || r.material || null;
  if (!mat) continue;
  atsMap[mat] = {
    material: mat,
    ats: r.ATS || 0,
    netSellPrice: r.netSellPrice || 0,
    currency: r.currency || 'USD',
    description: r.DESCRIPTION || r.description || '',
    family: (r.FAMILY || r.family || '').trim(),
    mgd2: (r.MGD2 || r.mgd2 || '').trim()
  };
}
return [{ json: { atsMap } }];

const materials = $input.all()[0].json.value;

return materials
  .filter(item => item.MaterialType !== 'ROH')  // ← add this line
  .map(item => ({
    json: {
      MATERIAL:       item.Material,
      DESCRIPTION:    item.Material_Description_.trim(),
      MATERIAL_TYPE:  item.MaterialType,
      MATERIAL_GROUP: item.MaterialGroup,
      PLANT:          item.Plant,
      FAMILY:         (item.Family || '').trim(),
      MGD2:           (item.MGD2   || '').trim()
    }
  }));

const rows = $input.all()[0].json.value;

const upcMap = {};
for (const row of rows) {
  if (row.ID) upcMap[row.ID] = row.UPC ?? '';
}

return [{ json: { upcMap } }];

const items = $input.all()[0].json.value;

const pricingMap = {};
items.forEach(item => {
  if (item.MATERIAL && item.CONDITIONRATEVALUE) {
    pricingMap[item.MATERIAL] = {
      material: item.MATERIAL,
      netSellPrice: item.CONDITIONRATEVALUE,
      currency: item.CONDITIONRATEVALUEUNIT
    };
  }
});

return Object.values(pricingMap).map(p => ({ json: p }));
